function lg_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function lg_lint(string $file): array {
    if (!function_exists('shell_exec')) return ['ok'=>false,'output'=>'shell_exec() is not available. Check Hostinger PHP Configuration -> disableFunctions.'];
    $out = shell_exec('php -l ' . escapeshellarg($file) . ' 2>&1');
    $text = trim((string)$out);
    return ['ok'=>($text!=='' && strpos($text,'No syntax errors detected')!==false),'output'=>$text];
}

