$lint = $writeOk ? lg_lint($target) : ['ok'=>false,'output'=>'Installer not staged.'];
$checks[] = ['label'=>'Real installer php -l','ok'=>(bool)$lint['ok'],'detail'=>(string)$lint['output']];

$all = true; foreach($checks as $c) if(!$c['ok']) $all=false;
